const crypto = require('crypto');

// Retrieve shared secret from environment
const secret = $env.N8N_WEBHOOK_SECRET || 'lendloop_n8n_hmac_secret_dev';
const headers = $input.first().json.headers || {};
const signatureHeader = headers['x-lendloop-signature'] || headers['X-LendLoop-Signature'];
const timestampHeader = headers['x-lendloop-timestamp'] || headers['X-LendLoop-Timestamp'];
let rawBody = $input.first().json.body;

if (typeof rawBody === 'object') {
  rawBody = JSON.stringify(rawBody);
}

if (!signatureHeader) {
  throw new Error('HMAC signature missing in X-LendLoop-Signature header.');
}

// Prevent replay attacks: ensure timestamp is within 15 minutes
if (timestampHeader) {
  const sentTime = parseInt(timestampHeader, 10);
  const now = Date.now();
  if (isNaN(sentTime) || Math.abs(now - sentTime) > 15 * 60 * 1000) {
    throw new Error('HMAC signature rejected: timestamp expired or clock drift exceeds 15 minutes.');
  }
}

// Compute expected HMAC SHA-256 signature
const payloadToVerify = timestampHeader ? `${timestampHeader}.${rawBody}` : rawBody;
const expectedSignature = crypto.createHmac('sha256', secret).update(payloadToVerify).digest('hex');

const sigBuffer = Buffer.from(signatureHeader, 'hex');
const expectedBuffer = Buffer.from(expectedSignature, 'hex');

if (sigBuffer.length !== expectedBuffer.length || !crypto.timingSafeEqual(sigBuffer, expectedBuffer)) {
  throw new Error('HMAC signature verification failed: payload may have been tampered with.');
}

const parsed = typeof rawBody === 'string' ? JSON.parse(rawBody) : rawBody;
return [{ json: parsed }];

const payload = $input.first().json;

// Format minimized notification for the tool owner
const startDateStr = new Date(payload.startDate).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
const endDateStr = new Date(payload.endDate).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });

return [{
  json: {
    channel: 'notification',
    recipientRole: 'lender',
    recipientEmail: payload.ownerEmail || 'owner@neighborhood.local',
    subject: `LendLoop: New borrow request for "${payload.toolTitle}"`,
    body: `Hi there! Your neighbor ${payload.requesterName} has requested to borrow your "${payload.toolTitle}" from ${startDateStr} to ${endDateStr}.${payload.note ? ` Note from neighbor: "${payload.note}"` : ''}`,
    actionUrl: `${$env.CONVEX_SITE_URL || 'http://localhost:3000'}/dashboard/incoming`,
    requestId: payload.requestId,
    toolId: payload.toolId,
    dispatchedAt: new Date().toISOString()
  }
}];

const payload = $input.first().json;

const statusLabel = payload.newStatus ? payload.newStatus.toUpperCase() : 'UPDATED';

return [{
  json: {
    channel: 'notification',
    recipientRole: 'borrower',
    recipientEmail: payload.borrowerEmail || 'borrower@neighborhood.local',
    subject: `LendLoop: Your request for "${payload.toolTitle || 'Tool'}" is ${statusLabel}`,
    body: `Hello! Your request to borrow "${payload.toolTitle || 'the tool'}" has been marked as ${statusLabel} by the owner.`,
    actionUrl: `${$env.CONVEX_SITE_URL || 'http://localhost:3000'}/dashboard/requests`,
    requestId: payload.requestId,
    status: payload.newStatus,
    dispatchedAt: new Date().toISOString()
  }
}];

const item = $input.first().json;

// Mock notification logger (can be connected to SMTP/Slack/Discord)
console.log(`[LendLoop Automation Notification Dispatch] TO: ${item.recipientEmail} | SUBJECT: ${item.subject}`);
console.log(`CONTENT: ${item.body}`);
console.log(`ACTION URL: ${item.actionUrl}`);

return [{
  json: {
    success: true,
    deliveredTo: item.recipientEmail,
    subject: item.subject,
    notificationChannel: 'simulated_email_log',
    status: 'delivered',
    timestamp: Date.now()
  }
}];
